var username = env.get('ZAPTEC_USERNAME') || '';
var password = env.get('ZAPTEC_PASSWORD') || '';

if (!username || !password) {
    node.error('Zaptec inloggegevens niet geconfigureerd! Stel omgevingsvariabelen ZAPTEC_USERNAME en ZAPTEC_PASSWORD in.');
    return null;
}

msg.url = 'https://api.zaptec.com/oauth/token';
msg.method = 'POST';
msg.headers = {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Accept': 'application/json'
};
msg.payload = 'grant_type=password&username=' + encodeURIComponent(username) + '&password=' + encodeURIComponent(password);

return msg;

if (msg.statusCode !== 200) {
    node.error('Zaptec authenticatie mislukt (HTTP ' + msg.statusCode + '): ' + JSON.stringify(msg.payload));
    return null;
}

if (!msg.payload || !msg.payload.access_token) {
    node.error('Geen access_token ontvangen van Zaptec: ' + JSON.stringify(msg.payload));
    return null;
}

var expiresIn = msg.payload.expires_in || 3600;
var expiryTime = Date.now() + (expiresIn - 120) * 1000;

flow.set('zaptec_token', msg.payload.access_token);
flow.set('zaptec_token_expiry', expiryTime);

var expiryDate = new Date(expiryTime);
node.log('Zaptec token opgeslagen, geldig tot: ' + expiryDate.toLocaleTimeString());

msg.payload = {
    status: 'success',
    message: 'Token opgeslagen',
    expires_at: expiryDate.toISOString()
};

return msg;

node.error('Authenticatie fout: ' + msg.error.message);
flow.set('zaptec_token', null);
flow.set('zaptec_token_expiry', null);
msg.payload = { status: 'error', error: msg.error.message };
return msg;

var token = flow.get('zaptec_token');
var expiry = flow.get('zaptec_token_expiry');

if (!token) {
    node.warn('Geen Zaptec token beschikbaar – wacht op authenticatie');
    return null;
}
if (expiry && Date.now() > expiry) {
    node.warn('Zaptec token verlopen – wacht op vernieuwing');
    return null;
}

var vrmId = env.get('VRM_PORTAL_ID') || '';
if (!vrmId) {
    node.error('VRM_PORTAL_ID omgevingsvariabele is niet ingesteld!');
    return null;
}

msg.url = 'https://api.zaptec.com/api/chargers';
msg.method = 'GET';
msg.headers = { 'Authorization': 'Bearer ' + token, 'Accept': 'application/json' };
msg.payload = {};
return msg;

if (msg.statusCode === 401) {
    node.warn('Zaptec API 401 – token vernieuwen');
    flow.set('zaptec_token', null);
    return null;
}
if (msg.statusCode !== 200) {
    node.error('Fout bij ophalen laadpalen (HTTP ' + msg.statusCode + ')');
    return null;
}

var chargers = (msg.payload && msg.payload.Data) ? msg.payload.Data : [];
if (chargers.length === 0) {
    node.warn('Geen laadpalen gevonden in Zaptec account');
    return null;
}

node.log('Gevonden laadpalen: ' + chargers.length);
var token = flow.get('zaptec_token');
var messages = [];

for (var i = 0; i < chargers.length; i++) {
    var c = chargers[i];
    messages.push({
        payload: {},
        charger_id: c.Id,
        charger_serial: (c.SerialNo || c.Id).replace(/[^a-zA-Z0-9_]/g, '_'),
        charger_name: c.Name || ('Laadpaal ' + (i + 1)),
        url: 'https://api.zaptec.com/api/chargers/' + c.Id + '/state',
        method: 'GET',
        headers: { 'Authorization': 'Bearer ' + token, 'Accept': 'application/json' }
    });
}

return [messages];

if (msg.statusCode === 401) {
    node.warn('Zaptec API 401 voor ' + msg.charger_serial);
    flow.set('zaptec_token', null);
    return null;
}
if (msg.statusCode !== 200) {
    node.error('Fout bij ophalen staat van ' + msg.charger_serial + ' (HTTP ' + msg.statusCode + ')');
    return null;
}

var states = Array.isArray(msg.payload) ? msg.payload : [];
var serial = msg.charger_serial;
var name   = msg.charger_name;

// Bouw StateId → waarde map
var sm = {};
for (var i = 0; i < states.length; i++) {
    var v = parseFloat(states[i].ValueAsString);
    sm[states[i].StateId] = isNaN(v) ? 0 : v;
}

// --- Zaptec StateIDs ---
// 513  Totaal actief vermogen (kW)  → ×1000 = W
// 501/502/503  Stroom L1/L2/L3 (A)
// 553/554/555  Spanning L1/L2/L3 (V)
// 521  Energie sessie (kWh)
// 552  Totale energie (kWh)
// 544  ChargerOperationMode (0-6)
// 520  Laadstroom setpoint (A)
var powerKW   = sm[513] || 0;
var iL1 = sm[501]||0, iL2 = sm[502]||0, iL3 = sm[503]||0;
var uL1 = sm[553]||230, uL2 = sm[554]||230, uL3 = sm[555]||230;
var eSess  = sm[521] || 0;
var eTotal = sm[552] || 0;
var opMode = sm[544] || 0;
var setI   = sm[520] || 0;

var pL1 = uL1 * iL1, pL2 = uL2 * iL2, pL3 = uL3 * iL3;
var totalW = (powerKW > 0) ? Math.round(powerKW * 1000) : Math.round(pL1 + pL2 + pL3);
var totalI = Math.round((iL1 + iL2 + iL3) * 10) / 10;

// Zaptec operatiemodus → Victron EV Charger status
// Victron: 0=Ontkoppeld 1=Verbonden 2=Opladen 3=Opgeladen 4=WachtZon 6=WachtStart
var modeMap = {0:0, 1:0, 2:6, 3:2, 4:3, 5:0, 6:4};
var victronStatus = (modeMap[opMode] !== undefined) ? modeMap[opMode] : 0;

// ───────────────────────────────────────────────────────────────────
// Bepaal VRM Portal ID en D-Bus instantie voor deze laadpaal
// ───────────────────────────────────────────────────────────────────
var vrmId        = env.get('VRM_PORTAL_ID') || '';
var instanceBase = parseInt(env.get('DBUS_INSTANCE_BASE') || '40');

var instanceMap = flow.get('charger_instances') || {};
if (!instanceMap[serial]) {
    var used = Object.values(instanceMap).map(Number);
    var next = instanceBase;
    while (used.indexOf(next) !== -1) next++;
    instanceMap[serial] = next;
    flow.set('charger_instances', instanceMap);
    node.log('Laadpaal "' + name + '" toegewezen aan D-Bus instantie ' + next);
}
var inst = instanceMap[serial];
var base = 'W/' + vrmId + '/evcharger/' + inst;

// ───────────────────────────────────────────────────────────────────
// Bouw array van MQTT write-berichten (Victron dbus-mqtt formaat)
// Elke waarde wordt gepubliceerd als: {"value": <getal>}
// ───────────────────────────────────────────────────────────────────
function val(v) { return JSON.stringify({value: v}); }

var mqttMsgs = [
    {topic: base + '/Ac/Power',           payload: val(totalW)},
    {topic: base + '/Ac/L1/Power',        payload: val(Math.round(pL1))},
    {topic: base + '/Ac/L2/Power',        payload: val(Math.round(pL2))},
    {topic: base + '/Ac/L3/Power',        payload: val(Math.round(pL3))},
    {topic: base + '/Ac/L1/Current',      payload: val(Math.round(iL1 * 10) / 10)},
    {topic: base + '/Ac/L2/Current',      payload: val(Math.round(iL2 * 10) / 10)},
    {topic: base + '/Ac/L3/Current',      payload: val(Math.round(iL3 * 10) / 10)},
    {topic: base + '/Ac/L1/Voltage',      payload: val(Math.round(uL1 * 10) / 10)},
    {topic: base + '/Ac/L2/Voltage',      payload: val(Math.round(uL2 * 10) / 10)},
    {topic: base + '/Ac/L3/Voltage',      payload: val(Math.round(uL3 * 10) / 10)},
    {topic: base + '/Ac/Energy/Forward',  payload: val(Math.round(eTotal * 1000) / 1000)},
    {topic: base + '/Ac/EnergySession',   payload: val(Math.round(eSess  * 1000) / 1000)},
    {topic: base + '/Status',             payload: val(victronStatus)},
    {topic: base + '/Current',            payload: val(totalI)},
    {topic: base + '/MaxCurrent',         payload: val(32)},
    {topic: base + '/SetCurrent',         payload: val(setI)},
    {topic: base + '/Mode',               payload: val(0)}
];

node.log('[' + name + '] ' + totalW + ' W | Status ' + victronStatus + ' | Sessie ' + eSess + ' kWh → inst ' + inst);

var debugMsg = {
    topic: serial,
    payload: {
        name: name, serial: serial, dbus_instance: inst,
        power: totalW, status: victronStatus,
        energy_session: eSess, energy_total: eTotal,
        current_l1: iL1, current_l2: iL2, current_l3: iL3,
        voltage_l1: uL1, voltage_l2: uL2, voltage_l3: uL3
    }
};

return [mqttMsgs, [debugMsg]];

var vrmId = env.get('VRM_PORTAL_ID') || '';
if (!vrmId) return null;

msg.topic   = 'R/' + vrmId + '/keepalive';
msg.payload = '';
return msg;

var instanceMap = flow.get('charger_instances') || {};
var vrmId = env.get('VRM_PORTAL_ID') || '(niet ingesteld)';

var result = {
    vrm_portal_id: vrmId,
    laadpaal_instanties: instanceMap,
    info: 'Elk serienummer is gekoppeld aan een Victron D-Bus EV Charger instantienummer'
};

for (var serial in instanceMap) {
    result['mqtt_basis_' + serial] = 'W/' + vrmId + '/evcharger/' + instanceMap[serial];
}

msg.payload = result;
return msg;
